-- Build independent MYOB workflow training.
insert into public.training_courses (slug,title,summary,category,country_focus,estimated_minutes,recommended_order,status,content_version,trademark_disclaimer,reviewed_by,last_reviewed_at,published_at,created_at,updated_at)
values ('myob-workflows-for-virtual-assistants','MYOB Workflows for Virtual Assistants','Independent MYOB workflow training for VAs supporting Australian businesses, covering customers and suppliers, invoices, bills, banking, GST/BAS reports, payroll/STP, reporting, and finance-review handoffs.','software','Australia',180,23,'draft',1,'MYOB is a trademark of its respective owner. This independent course is not affiliated with, certified by, or endorsed by MYOB. Product interfaces and features may change; verify current official MYOB documentation.',null,null,null,now(),now())
on conflict (slug) do update set title=excluded.title,summary=excluded.summary,country_focus='Australia',estimated_minutes=180,recommended_order=23,trademark_disclaimer=excluded.trademark_disclaimer,status='draft',published_at=null,reviewed_by=null,last_reviewed_at=null,updated_at=now();

insert into public.training_modules (course_id,title,summary,position) values ((select id from public.training_courses where slug='myob-workflows-for-virtual-assistants'),'MYOB Finance Admin','Understand the business file and transaction flow.',1) on conflict (course_id,position) do update set title=excluded.title,summary=excluded.summary,updated_at=now();

insert into public.training_lessons (module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at)
values ((select id from public.training_modules where course_id=(select id from public.training_courses where slug='myob-workflows-for-virtual-assistants') and position=1),'myob-business-file-contacts-and-access-boundaries','MYOB Business File, Contacts, and Access Boundaries','Australian clients may use MYOB Business or AccountRight with different workflows. Start by confirming the product, business entity, and role permissions before touching transactions or payroll.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Identify the correct MYOB business file and product","Maintain customer and supplier records","Use permissions safely"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"Australian clients may use MYOB Business or AccountRight with different workflows. Start by confirming the product, business entity, and role permissions before touching transactions or payroll."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["Business settings can include organisation details, financial year, and GST configuration.","Customer and supplier records feed sales and purchase workflows.","MYOB Business and AccountRight can present workflows differently.","Admin settings can have business-wide impact.","Access should match the assigned role."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Confirm MYOB product and business file.","Review permissions.","Map customer and supplier data rules.","Identify finance tasks you own.","Identify tax, payroll, BAS, and payment decisions requiring review.","Document the product-specific workflow."]},{"type":"callout","title":"Stay inside the role","text":"Do not change business GST, payroll, financial-year, or reporting settings simply because you have administrator access."},{"type":"callout","title":"Keep this current","text":"MYOB Business and AccountRight workflows can differ. Verify the client''s product and current official MYOB support documentation before following settings, payroll, STP, GST/BAS, banking, or reporting steps."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Following an AccountRight guide in MYOB Business without checking","Working in the wrong file","Duplicate contacts","Changing GST settings to fix one transaction","Using owner credentials"]},{"type":"scenario","title":"Practice scenario","text":"A client says ''we use MYOB'' but has two entities and two MYOB products. Explain what you verify before entering invoices."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Confirm product and entity.","Use least privilege.","Separate admin from settings authority.","Document workflow."]}]'::jsonb,30,1,false,1,null,null,now(),now())
on conflict (module_id,slug) do update set title=excluded.title,summary=excluded.summary,content=excluded.content,estimated_minutes=30,position=excluded.position,is_published=false,reviewed_by=null,last_reviewed_at=null,content_version=public.training_lessons.content_version+1,updated_at=now();

insert into public.training_lessons (module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at)
values ((select id from public.training_modules where course_id=(select id from public.training_courses where slug='myob-workflows-for-virtual-assistants') and position=1),'sales-purchases-invoices-bills-and-source-documents','Sales, Purchases, Invoices, Bills, and Source Documents','Sales and purchase records affect receivables, payables, GST, and reports. Clean source capture is more important than speed.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Support MYOB sales and purchase administration","Prevent duplicates","Keep source evidence connected"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"Sales and purchase records affect receivables, payables, GST, and reports. Clean source capture is more important than speed."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["Invoices, quotes, bills, and purchases have distinct workflows.","Contact identity, date, amount, account or category, and GST treatment matter.","Receipts and attachments support audit trail.","Credits and adjustments need authority.","Outstanding balances require current payment context."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Identify whether the source belongs to sales or purchases.","Search contact and duplicate records.","Enter approved transaction fields.","Attach or store evidence according to client workflow.","Use approved accounts and GST codes only.","Route exceptions.","Track approval and payment status.","Follow up outstanding items under policy."]},{"type":"callout","title":"Stay inside the role","text":"Do not change GST treatment, price, credits, or payment terms without authority."},{"type":"callout","title":"Keep this current","text":"MYOB Business and AccountRight workflows can differ. Verify the client''s product and current official MYOB support documentation before following settings, payroll, STP, GST/BAS, banking, or reporting steps."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Duplicate transactions","Wrong entity or contact","Guessing GST codes","Issuing credits to fix mistakes","Deleting source evidence"]},{"type":"scenario","title":"Practice scenario","text":"A supplier resends an invoice with a changed description but the same invoice number and total. Explain duplicate and version checks."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Source evidence first.","Check duplicates.","Use approved coding.","Escalate adjustments."]}]'::jsonb,30,2,false,1,null,null,now(),now())
on conflict (module_id,slug) do update set title=excluded.title,summary=excluded.summary,content=excluded.content,estimated_minutes=30,position=excluded.position,is_published=false,reviewed_by=null,last_reviewed_at=null,content_version=public.training_lessons.content_version+1,updated_at=now();

insert into public.training_modules (course_id,title,summary,position) values ((select id from public.training_courses where slug='myob-workflows-for-virtual-assistants'),'Banking, GST, and BAS','Prepare transactions and reports for review.',2) on conflict (course_id,position) do update set title=excluded.title,summary=excluded.summary,updated_at=now();

insert into public.training_lessons (module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at)
values ((select id from public.training_modules where course_id=(select id from public.training_courses where slug='myob-workflows-for-virtual-assistants') and position=2),'banking-matching-and-reconciliation-preparation-in-myob','Banking, Matching, and Reconciliation Preparation in MYOB','MYOB can support bank feeds and reconciliation workflows. The VA should focus on reliable matching and exception documentation rather than forcing transactions to reconcile.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Prepare bank transactions for reconciliation","Use matching carefully","Create exception queues"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"MYOB can support bank feeds and reconciliation workflows. The VA should focus on reliable matching and exception documentation rather than forcing transactions to reconcile."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["Bank activity must be matched to correct accounting records.","Suggested matches can be wrong.","Transfers, bank fees, payroll, merchant deposits, and duplicates need context.","Reconciliation supports reliable reports.","Unclear items should stay visible for review."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Review bank transaction.","Search for exact or approved match.","Compare date, amount, reference, and counterparty.","Use approved recurring rules if configured.","Flag unmatched or uncertain items.","Prepare reviewer exception list.","Document resolved items."]},{"type":"callout","title":"Stay inside the role","text":"Do not create or recode transactions only to clear the bank feed."},{"type":"callout","title":"Keep this current","text":"MYOB Business and AccountRight workflows can differ. Verify the client''s product and current official MYOB support documentation before following settings, payroll, STP, GST/BAS, banking, or reporting steps."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Accepting suggestions automatically","Reconciling duplicate imports","Guessing transfer direction","Hiding unknown items","Using personal judgment for tax-sensitive coding"]},{"type":"scenario","title":"Practice scenario","text":"Two MYOB transactions could both match one bank deposit. Explain how you investigate before matching."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Match from evidence.","Use automation cautiously.","Keep uncertainty visible.","Reconciliation quality matters."]}]'::jsonb,30,1,false,1,null,null,now(),now())
on conflict (module_id,slug) do update set title=excluded.title,summary=excluded.summary,content=excluded.content,estimated_minutes=30,position=excluded.position,is_published=false,reviewed_by=null,last_reviewed_at=null,content_version=public.training_lessons.content_version+1,updated_at=now();

insert into public.training_lessons (module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at)
values ((select id from public.training_modules where course_id=(select id from public.training_courses where slug='myob-workflows-for-virtual-assistants') and position=2),'gst-reports-bas-preparation-and-review-boundaries-in-myob','GST Reports, BAS Preparation, and Review Boundaries in MYOB','MYOB provides GST reports and Australian BAS-related workflows. Because source transaction coding drives these reports, the VA must avoid casual GST changes.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Recognize MYOB GST and BAS reporting tools","Prepare supporting reports","Keep lodgement and tax judgment with authorized professionals"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"MYOB provides GST reports and Australian BAS-related workflows. Because source transaction coding drives these reports, the VA must avoid casual GST changes."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["GST summary and detail reports can support BAS preparation.","Cash versus accrual treatment can affect reporting depending on business setup.","Business GST settings are high impact.","Corrections can affect prior periods.","BAS lodgement and adjustment decisions require appropriate authority."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Confirm business and reporting setup with reviewer.","Use approved transaction GST codes.","Run requested draft GST reports.","Identify anomalies and exceptions.","Link supporting transactions.","Route corrections and BAS decisions.","Do not lodge or declare unless authorized and qualified."]},{"type":"callout","title":"Stay inside the role","text":"This course does not teach the learner to determine GST liability or lodge BAS."},{"type":"callout","title":"Keep this current","text":"MYOB Business and AccountRight workflows can differ. Verify the client''s product and current official MYOB support documentation before following settings, payroll, STP, GST/BAS, banking, or reporting steps."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Switching cash or accrual basis to match expectations","Changing codes from guesswork","Treating report output as tax advice","Lodging from convenience","Correcting prior periods without review"]},{"type":"scenario","title":"Practice scenario","text":"GST report totals differ sharply from last quarter. Describe the transaction-level checks and reviewer handoff."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Reports depend on coding.","Preserve setup.","Investigate anomalies.","Keep BAS decisions with qualified owners."]}]'::jsonb,30,2,false,1,null,null,now(),now())
on conflict (module_id,slug) do update set title=excluded.title,summary=excluded.summary,content=excluded.content,estimated_minutes=30,position=excluded.position,is_published=false,reviewed_by=null,last_reviewed_at=null,content_version=public.training_lessons.content_version+1,updated_at=now();

insert into public.training_modules (course_id,title,summary,position) values ((select id from public.training_courses where slug='myob-workflows-for-virtual-assistants'),'Payroll, Reporting, and Simulation','Use MYOB payroll and reporting workflows safely.',3) on conflict (course_id,position) do update set title=excluded.title,summary=excluded.summary,updated_at=now();

insert into public.training_lessons (module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at)
values ((select id from public.training_modules where course_id=(select id from public.training_courses where slug='myob-workflows-for-virtual-assistants') and position=3),'myob-payroll-stp-super-and-employee-admin-handoff','MYOB Payroll, STP, Super, and Employee Admin Handoff','MYOB supports payroll, super, leave, and STP reporting in Australian products and plans. Official MYOB guidance distinguishes STP declarer responsibilities, so a VA must not assume the ability to click send equals authority to report to the ATO.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Understand MYOB payroll and STP workflow","Prepare employee and pay-run inputs","Recognize declarer and statutory boundaries"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"MYOB supports payroll, super, leave, and STP reporting in Australian products and plans. Official MYOB guidance distinguishes STP declarer responsibilities, so a VA must not assume the ability to click send equals authority to report to the ATO."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["Employee and payroll data must be complete and correctly configured.","STP reports salary, tax, and super information to the ATO.","A declarer is someone authorized to send STP information.","Pay items and reporting categories affect statutory output.","Super and leave workflows rely on correct setup."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Collect approved employee changes and timesheets.","Check missing approvals and anomalies.","Use existing approved payroll categories.","Prepare draft pay-run exceptions.","Route tax, super, leave, award, termination, and category questions.","Support reviewer checks.","Only an authorized declarer should submit STP under the client''s process."]},{"type":"callout","title":"Stay inside the role","text":"Do not add yourself as an STP declarer, change statutory categories, or submit reports merely because you have software access."},{"type":"callout","title":"Keep this current","text":"MYOB Business and AccountRight workflows can differ. Verify the client''s product and current official MYOB support documentation before following settings, payroll, STP, GST/BAS, banking, or reporting steps."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Changing pay categories without review","Submitting STP under another person''s authority","Sharing payroll data too widely","Guessing leave or super treatment","Assuming automation guarantees compliance"]},{"type":"scenario","title":"Practice scenario","text":"MYOB prompts you to add yourself as a declarer so you can complete the pay run. Explain why software convenience is not enough to establish authority."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Declarer status matters.","Payroll is sensitive.","Prepare and escalate.","Do not self-authorize."]}]'::jsonb,30,1,false,1,null,null,now(),now())
on conflict (module_id,slug) do update set title=excluded.title,summary=excluded.summary,content=excluded.content,estimated_minutes=30,position=excluded.position,is_published=false,reviewed_by=null,last_reviewed_at=null,content_version=public.training_lessons.content_version+1,updated_at=now();

insert into public.training_lessons (module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at)
values ((select id from public.training_modules where course_id=(select id from public.training_courses where slug='myob-workflows-for-virtual-assistants') and position=3),'myob-reports-accountant-handoff-and-composite-simulation','MYOB Reports, Accountant Handoff, and Composite Simulation','MYOB supports receivables and payables reconciliation reports, profit and loss, balance sheet, GST, payroll, and other reports. They are useful only when underlying records are accurate and the reader knows whether the report is draft or reviewed.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Prepare common MYOB reports for review","Trace exceptions to source records","Run a full MYOB admin simulation"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"MYOB supports receivables and payables reconciliation reports, profit and loss, balance sheet, GST, payroll, and other reports. They are useful only when underlying records are accurate and the reader knows whether the report is draft or reviewed."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["Report period and basis matter.","AP and AR reports surface outstanding balances.","GST and payroll reports can support regulated workflows but are not professional conclusions by themselves.","Unreconciled bank items reduce confidence.","Reviewer handoffs should be specific."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Confirm requested report and period.","Review known exceptions.","Run approved draft reports.","Investigate surprising items at source level.","Prepare a linked exception list.","Include payroll and GST items requiring qualified review.","Complete the fictional MYOB simulation and handoff."]},{"type":"callout","title":"Stay inside the role","text":"Do not call unreviewed reports final accounts, BAS, payroll compliance evidence, or tax advice."},{"type":"callout","title":"Keep this current","text":"MYOB Business and AccountRight workflows can differ. Verify the client''s product and current official MYOB support documentation before following settings, payroll, STP, GST/BAS, banking, or reporting steps."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Changing source data to make report totals look right","Wrong date range","Ignoring unreconciled items","Sending sensitive reports too broadly","Giving reviewer no source links"]},{"type":"scenario","title":"Practice scenario","text":"A fictional Australian retailer has duplicate supplier bills, an unmatched bank deposit, an overdue customer balance, a GST report anomaly, and an employee pay-category question. Prepare the MYOB actions and reviewer handoff."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Reports reflect source quality.","Label drafts.","Keep regulated decisions with reviewers.","Use exceptions to make review faster."]}]'::jsonb,30,2,false,1,null,null,now(),now())
