values ((select id from public.training_courses where slug='myob-workflows-for-virtual-assistants'),null,'MYOB Workflows Final Work Simulation','Complete a MYOB workflow simulation covering sales and purchases, banking, GST/BAS-sensitive reports, payroll/STP handoff, and finance reporting. The course is independent of MYOB and does not certify the learner or authorize tax/BAS/payroll decisions.','practical',null,1,false,now(),now());
